// T20: workbooks generated by the extracted html-data skill open in Chromium
// with current results, standard without network requests and offline
// recalculating with the embedded engine.
import assert from "node:assert/strict";
import { execFile } from "node:child_process";
import { promisify } from "node:util";
import { mkdtemp, cp } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { pathToFileURL, fileURLToPath } from "node:url";
import { chromium } from "playwright";

const run = promisify(execFile),
  repo = fileURLToPath(new URL("../../../", import.meta.url)),
  dir = await mkdtemp(join(tmpdir(), "html-office-skill-")),
  skill = join(dir, "plugin/skills/html-data");
await cp(join(repo, "plugin"), join(dir, "plugin"), { recursive: true });
const tool = (...args) =>
  run(process.execPath, [join(skill, "tools/workbook.mjs"), ...args], {
    cwd: dir,
  });
await tool(
  "new",
  join(dir, "budget.html"),
  "--model",
  join(skill, "examples/valid/budget.json"),
);
await tool(
  "apply",
  join(dir, "budget.html"),
  join(skill, "examples/patches/raise-price.json"),
  "--out",
  join(dir, "budget-2.html"),
);
await tool(
  "new",
  join(dir, "offline.html"),
  "--model",
  join(skill, "examples/valid/budget.json"),
  "--offline",
);
const browser = await chromium.launch();
try {
  const context = await browser.newContext(),
    requests = [],
    errors = [];
  await context.route(/^https?:\/\//, (route) => {
    requests.push(route.request().url());
    return route.abort();
  });
  for (const name of ["budget-2.html", "offline.html"]) {
    const page = await context.newPage();
    page.on("pageerror", (e) => errors.push(e.message));
    await page.goto(pathToFileURL(join(dir, name)).href);
    await page
      .getByText("Saved results are current.", { exact: true })
      .waitFor();
    await page.getByRole("button", { name: "Budget", exact: true }).click();
    assert.equal(
      await page.locator('#grid [data-cell="D4"]').textContent(),
      name === "budget-2.html" ? "€3,060" : "€1,140",
    );
    await page.close();
  }
  // Offline: an edit recalculates with the embedded engine.
  const page = await context.newPage();
  await page.goto(pathToFileURL(join(dir, "offline.html")).href);
  await page.getByText("Saved results are current.", { exact: true }).waitFor();
  await page.getByLabel("Cell address").fill("Inputs!B4");
  await page.getByRole("button", { name: "Inputs", exact: true }).click();
  await page.getByLabel("Cell address").fill("B4");
  await page.getByLabel("Cell address").press("Enter");
  await page.getByLabel("Cell value").fill("50");
  await page.getByRole("button", { name: "Apply edit" }).click();
  await page
    .getByText("Calculated locally. Unsaved changes.", { exact: true })
    .waitFor({ timeout: 60000 });
  assert.deepEqual(errors, []);
  assert.deepEqual(requests, [], "no network request");
  console.log("PASS skill-generated workbooks open, standard and offline");
} finally {
  await browser.close();
}
